INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_748d26e760e54651eaa0d8', 'ZM session stability gate', 'leonard.hayes@harmonygames.co', '["julia.lawson@harmonygames.co", "robert@harmonygames.co", "brian.foster@harmonygames.co", "vincent.parker@harmonygames.co"]', 'private', E'ZM session stability gate\nSep 24\n\nFriend sessions only help us if the game held up on the player''s phone and they played a build a real player gets.\n\nDevices\nSamsung is the one device group we check here: the Galaxy S, A and Z phones, which also show up as model numbers like SM-S, SM-A and SM-F. Other phones need nothing.\nA Samsung session counts once we have a clean pass covering that device. A pass covers a device only if it ran on that device. Once there is a pass, it covers all the Samsung sessions in the read.\nZOM-559 stays in the bug queue as usual. We aren''t waiting on it for this.\n\nPasses\nA pass is a clean test run of the build players get. Arthur Blake owns the Vision Bot job and says what its passes do and don''t cover.\n\nBuilds\nSessions on dev builds do not count. A dev build is anything that never went through a store.\n\nThese rules apply to every session in the read, whatever day it ran.\n\nLeonard', '[{"start": 0, "end": 26, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 26, "end": 919, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '3488805ab8', 'f_748d26e760e54651eaa0d8', '2025-09-24T15:12:40Z', '2025-09-24T15:30:02Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_c691d577b8f837eb4f9eaa', 'ZM sessions log note', 'julia.lawson@harmonygames.co', '["leonard.hayes@harmonygames.co", "robert@harmonygames.co"]', 'private', E'ZM sessions log note\n\nWhy tickets: Leonard wants the friend sessions tracked one by one so the read can be closed out properly, and the observers'' forms are spread over mail and Docs. So each session gets a ZOM ticket, and the workbook log has a row per ticket.\n\nI''m typing the tickets up in one batch today. Any form that comes in after this batch gets a ticket and a log row when I see it. Each ticket transcribes a dated observer form, so it carries the form date and the session date. The ticket date is just the day I typed it.\n\nThe phone goes in a comment on the ticket. Players are in my contacts so I can send the gift codes. Build, age and relation stay in the observer''s notes doc.\n\nClose-out when the read is done: counted goes to Done, not counted goes to Canceled.\n\nJulia', '[{"start": 0, "end": 21, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 21, "end": 784, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'ba438f6bc8', 'f_c691d577b8f837eb4f9eaa', '2025-09-30T16:24:03Z', '2025-09-30T16:35:20Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_524278b67bfa30dde78699', 'ZM session notes - Brian Foster - 01', 'brian.foster@harmonygames.co', '["julia.lawson@harmonygames.co"]', 'private', E'ZM session notes - Brian Foster - 01\nHost: Brian Foster\nObserver: Brian Foster\nPlayer: Emre Yıldız\nSession date: 2025-09-22\nAge: 35\nRelation: Kadıköy ekibi\nBuild: 0.3.38 (38)\nAudience: RPG\nStars: 5\nCoaching: none\n\nWhat I saw\nGot into the card deck right away and kept swapping cards between levels. Said the monster stats are what keeps him going. Didn''t want to give the phone back.\n', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 384, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '1aafd97d8a', 'f_524278b67bfa30dde78699', '2025-09-23T09:05:00Z', '2025-09-23T09:05:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_b66d5288a6d3ca9d4d03b6', 'ZM session notes - Brian Foster - 02', 'brian.foster@harmonygames.co', '["julia.lawson@harmonygames.co"]', 'private', E'ZM session notes - Brian Foster - 02\nHost: Brian Foster\nObserver: Brian Foster\nPlayer: Selin Aydın\nSession date: 2025-09-22\nAge: 30\nRelation: Kadıköy ekibi\nBuild: 0.3.38 (38)\nAudience: RPG\nStars: 5\nCoaching: none\n\nWhat I saw\nPlayed 40 minutes without stopping. Liked that items do different damage, compared two of them side by side before picking.\n', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 349, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '18ad5c1f81', 'f_b66d5288a6d3ca9d4d03b6', '2025-09-23T09:06:37Z', '2025-09-23T09:06:37Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_8dab41c358ba484acad83d', 'ZM session notes - Brian Foster - 03', 'brian.foster@harmonygames.co', '["julia.lawson@harmonygames.co"]', 'private', E'ZM session notes - Brian Foster - 03\nHost: Brian Foster\nObserver: Brian Foster\nPlayer: Burak Demir\nSession date: 2025-09-22\nAge: 39\nRelation: Kadıköy ekibi\nBuild: 0.3.38 (38)\nAudience: RPG\nStars: 4\nCoaching: none\n\nWhat I saw\nLiked the boss fight more than the matching part. Wanted to see his stats on one screen.\n', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 314, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'aca0770b4e', 'f_8dab41c358ba484acad83d', '2025-09-23T09:08:14Z', '2025-09-23T09:08:14Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_abf945213ee8762fbdc083', 'ZM session notes - Brian Foster - 04', 'brian.foster@harmonygames.co', '["julia.lawson@harmonygames.co"]', 'private', E'ZM session notes - Brian Foster - 04\nHost: Brian Foster\nObserver: Brian Foster\nPlayer: Mert Şahin\nSession date: 2025-09-22\nAge: 44\nRelation: Kadıköy ekibi\nBuild: 0.3.38 (38)\nAudience: RPG\nStars: 5\nCoaching: none\n\nWhat I saw\nAsked how far the card levels go. Upgraded everything he could and replayed a level to get more stars.\n', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 327, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'd3c3752e07', 'f_abf945213ee8762fbdc083', '2025-09-23T09:09:51Z', '2025-09-23T09:09:51Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_36b61fd6f9ef6ec45cf759', 'ZM session notes - Brian Foster - 05', 'brian.foster@harmonygames.co', '["julia.lawson@harmonygames.co"]', 'private', E'ZM session notes - Brian Foster - 05\nHost: Brian Foster\nObserver: Brian Foster\nPlayer: Deniz Kaya\nSession date: 2025-09-22\nAge: 39\nRelation: Kadıköy ekibi\nBuild: 0.3.38 (38)\nAudience: RPG\nStars: 5\nCoaching: none\n\nWhat I saw\nVery focused, hardly talked. Afterwards said it feels like a small RPG with a match board on top, in a good way.\n', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 337, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '105b83c74e', 'f_36b61fd6f9ef6ec45cf759', '2025-09-23T09:11:28Z', '2025-09-23T09:11:28Z');
