VALUES ('f_548e4061239f8bbb1ebef1', 'ZM session notes - Brian Foster - 06', 'brian.foster@harmonygames.co', '["julia.lawson@harmonygames.co"]', 'private', E'ZM session notes - Brian Foster - 06\nHost: Brian Foster\nObserver: Brian Foster\nPlayer: Ece Arslan\nSession date: 2025-09-22\nAge: 33\nRelation: Kadıköy ekibi\nBuild: 0.3.38 (38)\nAudience: RPG\nStars: 4.5\nCoaching: none\n\nWhat I saw\nEnjoyed the grenades most. Complained a bit about the crowded pile but kept playing.\n', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 311, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '43bb5f9762', 'f_548e4061239f8bbb1ebef1', '2025-09-23T09:13:05Z', '2025-09-23T09:13:05Z');
