VALUES ('f_3ff040d3a2e345719d4a70', 'ZM session notes - Brian Foster - 07', 'brian.foster@harmonygames.co', '["julia.lawson@harmonygames.co"]', 'private', E'ZM session notes - Brian Foster - 07\nHost: Brian Foster\nObserver: Brian Foster\nPlayer: Kaan Öztürk\nSession date: 2025-09-22\nAge: 31\nRelation: Kadıköy ekibi\nBuild: 0.3.38 (38)\nAudience: RPG\nStars: 5\nCoaching: none\n\nWhat I saw\nSaid the zombie waves give it a tension normal match games don''t have. Wanted a harder mode.\n', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 318, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '900e6c1b51', 'f_3ff040d3a2e345719d4a70', '2025-09-23T09:14:42Z', '2025-09-23T09:14:42Z');
