INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('4bd8937a7616a1ba2d6e6151ffc3a492', '1758553214.330914', 'C090N54TG79', 'message', 'EMPLOYEE_0005_SLACK_ID', '<@EMPLOYEE_0038_SLACK_ID> quick one on your note. "25–45 casual and/or RPG gamer friends", is that 25 to 45 people or 25 to 45 years old?', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-22T15:00:14.330914Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('12b40a5b7cc18f7c9fe2d0a9e0e929b4', '1758554405.774120', 'C090N54TG79', 'message', 'EMPLOYEE_0038_SLACK_ID', '<@EMPLOYEE_0005_SLACK_ID> age. 25–45 years old, not a headcount', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-22T15:20:05.774120Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('4500761ad805eeda66272ec37c91a8ef', '1758555040.262718', 'C0880U9751A', 'message', 'EMPLOYEE_0005_SLACK_ID', 'hey all, passing this on from Leonard''s note in <#C090N54TG79>: everyone should get a few friends to try ZM: 25–45 year olds, casual and/or RPG gamers, not kids. No coaching, just observe and collect honest reactions. If you run any, write one notes doc per session with their age, how you know them, the build, casual or RPG and their stars, and share it with me. Then send me a short mail with host, day, how many sessions and whether there was any coaching, so I can log them', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-22T15:30:40.262718Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('5e2947d9447f26c28b465f4fd64254d3', '1758658884.207315', 'D076RBM29JS', 'message', 'EMPLOYEE_0005_SLACK_ID', 'paylaştığın notlara bakıyorum, Kadıköy ekibi kim ya? nereden tanıyorsun onları', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-23T20:21:24.207315Z', '{}');
